22	export async function purchaseDomain(prev: any, formData: FormData): Promise<{ error?: string }> {
23	  const user = await requireUser();
24	  if (!registrarConfigured()) {
25	    return { error: "Domain registration is not configured yet (name.com API keys missing)." };
26	  }
27	  const contactSchema = z.object({
28	    firstName: z.string().min(1).max(60),
29	    lastName: z.string().min(1).max(60),
30	    address1: z.string().min(1).max(120),
31	    city: z.string().min(1).max(60),
32	    stateProvince: z.string().min(1).max(60),
33	    postalCode: z.string().min(1).max(20),
34	    country: z.string().length(2),
35	    phone: z.string().regex(/^\+\d{1,3}\.\d{4,14}$/, "Phone format: +1.5551234567"),
36	    email: z.string().email(),
37	  });
38	  const domain = String(formData.get("domain") ?? "").toLowerCase().trim();
39	  if (!DOMAIN_RE.test(domain)) return { error: "Invalid domain name." };
40	
41	  const contactParsed = contactSchema.safeParse({
42	    firstName: formData.get("firstName"),
43	    lastName: formData.get("lastName"),
44	    address1: formData.get("address1"),
45	    city: formData.get("city"),
46	    stateProvince: formData.get("stateProvince"),
47	    postalCode: formData.get("postalCode"),
48	    country: String(formData.get("country") ?? "").toUpperCase(),
49	    phone: formData.get("phone"),
50	    email: formData.get("email"),
51	  });
52	  if (!contactParsed.success) {
53	    return { error: contactParsed.error.issues[0]?.message ?? "Invalid registrant contact." };
54	  }
55	
56	  if (await db.domain.findUnique({ where: { name: domain } })) {
57	    return { error: "This domain is already managed by another account." };
58	  }
59	
60	  // Live availability + price from name.com
61	  let priceCents: number;
62	  try {
63	    const [check] = await checkDomains([domain]);
64	    if (!check) return { error: "Could not check availability. Try again." };
65	    if (!check.available) return { error: "Domain is not available." };
66	    if (check.premium) return { error: "Premium domains are not supported yet." };
67	    if (check.priceCents === null) return { error: "No price available for this TLD." };
68	    priceCents = check.priceCents;
69	  } catch (e: any) {
70	    return { error: String(e?.message ?? e).slice(0, 200) };
71	  }
72	
73	  if (user.balanceCents < priceCents) {
74	    return { error: `Insufficient balance — this domain costs $${(priceCents / 100).toFixed(2)}/yr.` };
75	  }
76	
77	  const record = await db.$transaction(async (tx) => {
78	    await tx.user.update({ where: { id: user.id }, data: { balanceCents: { decrement: priceCents } } });
79	    await tx.walletTransaction.create({
80	      data: { userId: user.id, amountCents: -priceCents, description: `Domain registration: ${domain}` },
81	    });
82	    return tx.domain.create({
83	      data: { name: domain, userId: user.id, priceCents, status: "PENDING", registrar: "name.com" },
84	    });
85	  });
86	
87	  try {
88	    const { expiresAt } = await registerDomain(domain, 1, contactParsed.data as RegistrantContact, priceCents);
89	    const info = expiresAt ? { expires: expiresAt } : await domainInfo(domain).catch(() => ({ expires: undefined }));
90	    await db.domain.update({
91	      where: { id: record.id },
92	      data: {
93	        status: "ACTIVE",
94	        registeredAt: new Date(),
95	        expiresAt: info.expires ?? new Date(Date.now() + 365 * 86400_000),
96	      },
97	    });
98	    await db.auditLog.create({ data: { userId: user.id, action: "domain.register", detail: domain } });
99	    await db.notification.create({
100	      data: { userId: user.id, title: `Domain registered: ${domain}`, href: `/dashboard/domains/${record.id}` },
101	    });
102	  } catch (e: any) {
103	    await db.$transaction([
104	      db.user.update({ where: { id: user.id }, data: { balanceCents: { increment: priceCents } } }),
105	      db.walletTransaction.create({
106	        data: { userId: user.id, amountCents: priceCents, description: `Refund: failed registration ${domain}` },
107	      }),
108	      db.domain.update({
109	        where: { id: record.id },
110	        data: { status: "FAILED", error: String(e?.message ?? e).slice(0, 500) },
111	      }),
112	    ]);
113	    return { error: `Registration failed: ${String(e?.message ?? e).slice(0, 200)} (you were refunded).` };
114	  }
115	  redirect(`/dashboard/domains/${record.id}`);
116	}
