121	  if (!domain || (domain.userId !== user.id && user.role !== "ADMIN")) return { error: "Not found." };
122	  const owner = await db.user.findUnique({ where: { id: domain.userId } });
123	  if (!owner || owner.balanceCents < domain.priceCents) return { error: "Insufficient balance." };
