129	  }
130	  await db.$transaction([
131	    db.user.update({ where: { id: domain.userId }, data: { balanceCents: { decrement: domain.priceCents } } }),
132	    db.walletTransaction.create({
133	      data: { userId: domain.userId, amountCents: -domain.priceCents, description: `Domain renewal: ${domain.name}` },
134	    }),
135	    db.domain.update({
136	      where: { id: domainId },
137	      data: {
138	        expiresAt: new Date((domain.expiresAt ?? new Date()).getTime() + 365 * 86400_000),
139	        status: "ACTIVE",
140	      },
