167	export async function addDnsRecord(prev: any, formData: FormData): Promise<{ error?: string }> {
168	  const domainId = String(formData.get("domainId") ?? "");
169	  let ctx;
170	  try {
171	    ctx = await ownedDomain(domainId);
172	  } catch (e: any) {
173	    return { error: e.message };
174	  }
175	  const parsed = z
176	    .object({
177	      name: z.string().max(120).default(""),
178	      type: z.enum(RECORD_TYPES),
179	      address: z.string().min(1).max(500),
180	      ttl: z.coerce.number().int().min(60).max(86400).default(300),
181	      mxPref: z.coerce.number().int().min(0).max(65535).optional(),
182	    })
183	    .safeParse({
184	      name: formData.get("name") ?? "",
185	      type: formData.get("type"),
186	      address: formData.get("address"),
187	      ttl: formData.get("ttl") || 300,
188	      mxPref: formData.get("mxPref") || undefined,
189	    });
190	  if (!parsed.success) return { error: parsed.error.issues[0]?.message ?? "Invalid record." };
191	
192	  // "@" or blank => apex (name.com uses empty host for apex)
193	  const host = ["@", ""].includes(parsed.data.name.trim()) ? "" : parsed.data.name.trim();
194	  try {
195	    await addRecord(ctx.domain.name, {
196	      host,
197	      type: parsed.data.type,
198	      answer: parsed.data.address,
199	      ttl: parsed.data.ttl,
200	      priority: parsed.data.type === "MX" || parsed.data.type === "SRV" ? parsed.data.mxPref ?? 10 : undefined,
201	    });
202	  } catch (e: any) {
203	    return { error: String(e?.message ?? e).slice(0, 200) };
204	  }
205	  revalidatePath(`/dashboard/domains/${domainId}`);
