223	    if (!match) return { error: "Record not found (it may have already been removed)." };
224	    await deleteRecord(ctx.domain.name, match.id);
225	  } catch (e: any) {
226	    return { error: String(e?.message ?? e).slice(0, 200) };
227	  }
228	  revalidatePath(`/dashboard/domains/${domainId}`);
