  const addons = (server.addons ?? {}) as { malwareScanner?: boolean; dailyBackup?: boolean; docker?: boolean };
  const setup: string[] = [];
  if (addons.docker) setup.push("curl -fsSL https://get.docker.com | sh && systemctl enable --now docker");
  if (addons.malwareScanner)
    setup.push("(apt-get install -y clamav clamav-daemon || dnf install -y clamav) && (systemctl enable --now clamav-freshclam || true)");
