"use server";

import { revalidatePath } from "next/cache";
import { redirect } from "next/navigation";
import { z } from "zod";
import type { NodeStatus } from "@prisma/client";
import { db } from "@/lib/db";
import { requireAdmin } from "@/lib/auth";
import { pveFor } from "@/lib/proxmox";

/**
 * Admin CRUD + health checks for compute nodes (Proxmox hypervisors).
 *
 * Multi-node correctness rules enforced here:
 *  - Each node lives in its own NAT /24 (`subnetPrefix`). Two nodes may reuse
 *    the same guest-IP range ONLY if they sit in different subnets — so we only
 *    flag an IP overlap when the subnetPrefix matches.
 *  - SSH DNAT forwards happen on each node's own host, so port ranges may repeat
 *    across different hosts. They only conflict when two Node rows point at the
 *    same public IP (same host) with overlapping port ranges.
 *  - `natChain` is the iptables chain the worker rebuilds from the DB; it must be
 *    globally unique so one node's rebuild never clobbers another's rules.
 */

type FormState = { error?: string; ok?: boolean };

async function audit(userId: string | null, action: string, detail?: string) {
  await db.auditLog.create({ data: { userId, action, detail } });
}

function rangesOverlap(aStart: number, aEnd: number, bStart: number, bEnd: number): boolean {
  return aStart <= bEnd && bStart <= aEnd;
}

/** Suggest sane, non-colliding defaults for the Nth node (1-based ordinal of the new node). */
export async function suggestNodeDefaults(): Promise<{
  ordinal: number;
  subnetPrefix: string;
  natChain: string;
  ipStart: number;
  ipEnd: number;
  sshPortStart: number;
  sshPortEnd: number;
}> {
  await requireAdmin();
  const count = await db.node.count();
  const ordinal = count + 1;
  // node #1 → 10.20.0. / NXEON_FWD ; node #2 → 10.20.1. / NXEON_FWD_N2 ; ...
  const subnetPrefix = `10.20.${ordinal - 1}.`;
  const natChain = ordinal === 1 ? "NXEON_FWD" : `NXEON_FWD_N${ordinal}`;
  return { ordinal, subnetPrefix, natChain, ipStart: 100, ipEnd: 250, sshPortStart: 20000, sshPortEnd: 29999 };
}

const nodeSchema = z.object({
  name: z.string().min(1).max(60).regex(/^[a-zA-Z0-9._-]+$/, "Name: letters, digits, . _ - only."),
  pveNode: z.string().min(1).max(60).regex(/^[a-zA-Z0-9.-]+$/, "Invalid Proxmox node name."),
  apiUrl: z.string().url().max(200).refine((u) => u.startsWith("http"), "API URL must be http(s)."),
  tokenId: z.string().min(1).max(120).regex(/^[^\s]+![^\s]+$/, "Token ID looks like user@realm!tokenname."),
  tokenSecret: z.string().min(1).max(200),
  publicIp: z.string().min(1).max(60),
  bridge: z.string().min(1).max(20).regex(/^[a-z0-9]+$/, "Bridge: e.g. vmbr1."),
  subnetPrefix: z
    .string()
    .regex(/^\d{1,3}\.\d{1,3}\.\d{1,3}\.$/, "Subnet prefix must be a /24 like 10.20.1. (trailing dot)."),
  ipStart: z.coerce.number().int().min(2).max(254),
  ipEnd: z.coerce.number().int().min(2).max(254),
  sshPortStart: z.coerce.number().int().min(1024).max(65535),
  sshPortEnd: z.coerce.number().int().min(1024).max(65535),
  natChain: z.string().min(1).max(40).regex(/^[A-Z0-9_]+$/, "NAT chain: UPPERCASE letters, digits, _ only."),
  storageNvme: z.string().min(1).max(60),
  storageHdd: z.string().min(1).max(60),
  capacityRamMB: z.coerce.number().int().min(1024).max(4_000_000),
  enabled: z.boolean().default(true),
  isPrimary: z.boolean().default(false),
  status: z.enum(["ONLINE", "OFFLINE", "MAINTENANCE"]).default("ONLINE"),
});

type NodeInput = z.infer<typeof nodeSchema>;

function parseNodeForm(formData: FormData) {
  return nodeSchema.safeParse({
    name: (formData.get("name") ?? "").toString().trim(),
    pveNode: (formData.get("pveNode") ?? "").toString().trim(),
    apiUrl: (formData.get("apiUrl") ?? "").toString().trim(),
    tokenId: (formData.get("tokenId") ?? "").toString().trim(),
    tokenSecret: (formData.get("tokenSecret") ?? "").toString().trim(),
    publicIp: (formData.get("publicIp") ?? "").toString().trim(),
    bridge: (formData.get("bridge") ?? "vmbr1").toString().trim(),
    subnetPrefix: (formData.get("subnetPrefix") ?? "").toString().trim(),
    ipStart: formData.get("ipStart"),
    ipEnd: formData.get("ipEnd"),
    sshPortStart: formData.get("sshPortStart"),
    sshPortEnd: formData.get("sshPortEnd"),
    natChain: (formData.get("natChain") ?? "").toString().trim(),
    storageNvme: (formData.get("storageNvme") ?? "vmdata").toString().trim(),
    storageHdd: (formData.get("storageHdd") ?? "vmdata-hdd").toString().trim(),
    capacityRamMB: formData.get("capacityRamMB"),
    enabled: formData.get("enabled") != null,
    isPrimary: formData.get("isPrimary") != null,
    status: (formData.get("status") ?? "ONLINE").toString(),
  });
}

/**
 * Validate a proposed node's ranges/uniqueness against all other nodes.
 * `selfId` excludes the row being edited. Returns an error string or null.
 */
async function validateAgainstExisting(data: NodeInput, selfId?: string): Promise<string | null> {
  if (data.ipEnd < data.ipStart) return "Guest IP range invalid: ipEnd must be ≥ ipStart.";
  if (data.sshPortEnd < data.sshPortStart) return "SSH port range invalid: end must be ≥ start.";

  const others = await db.node.findMany({
    where: selfId ? { id: { not: selfId } } : {},
    select: {
      name: true,
      publicIp: true,
      subnetPrefix: true,
      ipStart: true,
      ipEnd: true,
      sshPortStart: true,
      sshPortEnd: true,
      natChain: true,
      isPrimary: true,
    },
  });

  for (const o of others) {
    if (o.natChain === data.natChain) {
      const next = data.natChain === "NXEON_FWD" ? "NXEON_FWD_N2" : `${data.natChain}_X`;
      return `NAT chain "${data.natChain}" is already used by node "${o.name}". Each node needs a globally unique chain (e.g. ${next}).`;
    }
    // IP ranges only collide inside the same /24 subnet.
    if (o.subnetPrefix === data.subnetPrefix && rangesOverlap(data.ipStart, data.ipEnd, o.ipStart, o.ipEnd)) {
      return `Guest IP range ${data.subnetPrefix}${data.ipStart}-${data.ipEnd} overlaps node "${o.name}" (${o.subnetPrefix}${o.ipStart}-${o.ipEnd}). Give this node its own /24, e.g. bump subnetPrefix to 10.20.N.`;
    }
    // SSH ports only collide when two nodes share the same public host.
    if (
      o.publicIp === data.publicIp &&
      rangesOverlap(data.sshPortStart, data.sshPortEnd, o.sshPortStart, o.sshPortEnd)
    ) {
      return `SSH port range ${data.sshPortStart}-${data.sshPortEnd} overlaps node "${o.name}" on the same host ${data.publicIp}. Use a distinct port range for co-hosted nodes.`;
    }
    if (data.isPrimary && o.isPrimary) {
      return `Node "${o.name}" is already the primary. Only one node can be primary.`;
    }
  }
  return null;
}

export async function addNode(_prev: FormState, formData: FormData): Promise<FormState> {
  const admin = await requireAdmin();
  const parsed = parseNodeForm(formData);
  if (!parsed.success) return { error: parsed.error.issues[0]?.message ?? "Invalid node details." };
  const data = parsed.data;

  if (await db.node.findUnique({ where: { name: data.name } })) {
    return { error: `A node named "${data.name}" already exists.` };
  }
  const rangeError = await validateAgainstExisting(data);
  if (rangeError) return { error: rangeError };

  let created;
  try {
    created = await db.node.create({ data });
  } catch (e: any) {
    return { error: `Could not create node: ${String(e?.message ?? e).slice(0, 200)}` };
  }
  await audit(admin.id, "node.create", `${data.name} (${data.pveNode} @ ${data.apiUrl})`);
  revalidatePath("/admin/nodes");
  revalidatePath("/admin/infrastructure");
  redirect(`/admin/nodes/${created.id}`);
}

export async function updateNode(_prev: FormState, formData: FormData): Promise<FormState> {
  const admin = await requireAdmin();
  const id = (formData.get("id") ?? "").toString();
  const existing = await db.node.findUnique({ where: { id } });
  if (!existing) return { error: "Node not found." };

  const parsed = parseNodeForm(formData);
  if (!parsed.success) return { error: parsed.error.issues[0]?.message ?? "Invalid node details." };
  const data = parsed.data;

  const nameClash = await db.node.findUnique({ where: { name: data.name } });
  if (nameClash && nameClash.id !== id) return { error: `A node named "${data.name}" already exists.` };

  const rangeError = await validateAgainstExisting(data, id);
  if (rangeError) return { error: rangeError };

  try {
    await db.node.update({ where: { id }, data });
  } catch (e: any) {
    return { error: `Could not update node: ${String(e?.message ?? e).slice(0, 200)}` };
  }
  await audit(admin.id, "node.update", `${data.name} (${id})`);
  revalidatePath("/admin/nodes");
  revalidatePath(`/admin/nodes/${id}`);
  revalidatePath("/admin/infrastructure");
  return { ok: true };
}

export async function setNodeEnabled(id: string, enabled: boolean): Promise<FormState> {
  const admin = await requireAdmin();
  const node = await db.node.findUnique({ where: { id } });
  if (!node) return { error: "Node not found." };
  await db.node.update({ where: { id }, data: { enabled } });
  await audit(admin.id, enabled ? "node.enable" : "node.disable", node.name);
  revalidatePath("/admin/nodes");
  revalidatePath(`/admin/nodes/${id}`);
  return { ok: true };
}

export async function setNodeStatus(id: string, status: NodeStatus): Promise<FormState> {
  const admin = await requireAdmin();
  const node = await db.node.findUnique({ where: { id } });
  if (!node) return { error: "Node not found." };
  await db.node.update({ where: { id }, data: { status } });
  await audit(admin.id, "node.status", `${node.name} → ${status}`);
  revalidatePath("/admin/nodes");
  revalidatePath(`/admin/nodes/${id}`);
  return { ok: true };
}

export type TestNodeResult = {
  ok: boolean;
  message: string;
  uptimeSec?: number;
  ramTotal?: number;
  ramUsed?: number;
  cpu?: number;
  pveVersion?: string;
  checkedAt: string;
};

/** Live health check: hit the node's Proxmox API, record status + lastSeenAt. */
export async function testNode(id: string): Promise<TestNodeResult> {
  const admin = await requireAdmin();
  const node = await db.node.findUnique({ where: { id } });
  const checkedAt = new Date().toISOString();
  if (!node) return { ok: false, message: "Node not found.", checkedAt };

  const client = pveFor({
    apiUrl: node.apiUrl,
    pveNode: node.pveNode,
    tokenId: node.tokenId,
    tokenSecret: node.tokenSecret,
  });

  try {
    const s = await client.get(`/nodes/${client.node}/status`);
    await db.node.update({
      where: { id },
      data: {
        lastSeenAt: new Date(),
        // Don't override an operator-set MAINTENANCE flag with ONLINE.
        status: node.status === "MAINTENANCE" ? "MAINTENANCE" : "ONLINE",
      },
    });
    await audit(admin.id, "node.test.ok", node.name);
    revalidatePath("/admin/nodes");
    revalidatePath(`/admin/nodes/${id}`);
    return {
      ok: true,
      message: "Proxmox API reachable.",
      uptimeSec: typeof s?.uptime === "number" ? s.uptime : undefined,
      ramTotal: s?.memory?.total,
      ramUsed: s?.memory?.used,
      cpu: typeof s?.cpu === "number" ? s.cpu : undefined,
      pveVersion: typeof s?.pveversion === "string" ? s.pveversion : undefined,
      checkedAt,
    };
  } catch (e: any) {
    await db.node.update({
      where: { id },
      data: { status: node.status === "MAINTENANCE" ? "MAINTENANCE" : "OFFLINE" },
    });
    await audit(admin.id, "node.test.fail", `${node.name}: ${String(e?.message ?? e).slice(0, 160)}`);
    revalidatePath("/admin/nodes");
    revalidatePath(`/admin/nodes/${id}`);
    return { ok: false, message: `Unreachable: ${String(e?.message ?? e).slice(0, 200)}`, checkedAt };
  }
}

export async function deleteNode(id: string): Promise<FormState> {
  const admin = await requireAdmin();
  const node = await db.node.findUnique({
    where: { id },
    include: { _count: { select: { servers: true } } },
  });
  if (!node) return { error: "Node not found." };
  if (node.isPrimary) return { error: "Refusing to delete the primary node." };
  if (node._count.servers > 0) {
    return {
      error: `Cannot delete "${node.name}" — ${node._count.servers} server(s) are still assigned to it. Migrate or remove them first.`,
    };
  }
  await db.node.delete({ where: { id } });
  await audit(admin.id, "node.delete", node.name);
  revalidatePath("/admin/nodes");
  revalidatePath("/admin/infrastructure");
  redirect("/admin/nodes");
}

