function Field({
  label,
  name,
  defaultValue,
  placeholder,
  type = "text",
  required = true,
  mono = false,
  hint,
}: {
  label: string;
  name: string;
  defaultValue?: string | number;
  placeholder?: string;
  type?: string;
  required?: boolean;
  mono?: boolean;
  hint?: string;
}) {
  return (
    <div>
      <label className="label">{label}</label>
      <input
        className={`input ${mono ? "font-mono text-xs" : ""}`}
        name={name}
        type={type}
        defaultValue={defaultValue}
        placeholder={placeholder}
        required={required}
      />
      {hint && <p className="mt-1 text-xs text-slate-500">{hint}</p>}
    </div>
  );
}

/** Shared add/edit form. Pass `defaults` for a new node, `node` for editing. */
