/** Live health-check button that surfaces the result inline. */
export function TestNodeButton({ id, compact = false }: { id: string; compact?: boolean }) {
  const [pending, start] = useTransition();
  const [result, setResult] = useState<TestNodeResult | null>(null);

  const run = () => start(async () => setResult(await testNode(id)));

  if (compact) {
    return (
      <button className="btn-secondary py-1.5" disabled={pending} onClick={run} title="Health check">
        {pending ? "Testing…" : "Test"}
      </button>
    );
  }

  return (
    <div className="space-y-3">
      <button className="btn-secondary" disabled={pending} onClick={run}>
        {pending ? "Contacting Proxmox…" : "Run health check"}
      </button>
      {result && (
        <div
          className={`rounded-xl border px-4 py-3 text-sm ${
            result.ok
              ? "border-emerald-500/30 bg-emerald-500/10 text-emerald-200"
              : "border-red-500/30 bg-red-500/10 text-red-300"
          }`}
        >
          <p className="font-medium">{result.ok ? "Reachable" : "Unreachable"} — {result.message}</p>
          {result.ok && (
            <dl className="mt-2 grid grid-cols-2 gap-x-6 gap-y-1 text-xs text-slate-300 sm:grid-cols-3">
              {result.uptimeSec != null && (
                <div className="flex justify-between gap-2">
                  <dt className="text-slate-500">Uptime</dt>
                  <dd>{Math.floor(result.uptimeSec / 86400)}d {Math.floor((result.uptimeSec % 86400) / 3600)}h</dd>
                </div>
              )}
              {result.ramTotal != null && (
                <div className="flex justify-between gap-2">
                  <dt className="text-slate-500">RAM used</dt>
                  <dd>
                    {((result.ramUsed ?? 0) / 1024 ** 3).toFixed(1)}/{(result.ramTotal / 1024 ** 3).toFixed(0)} GB
                  </dd>
                </div>
              )}
              {result.cpu != null && (
                <div className="flex justify-between gap-2">
                  <dt className="text-slate-500">CPU</dt>
                  <dd>{(result.cpu * 100).toFixed(1)}%</dd>
                </div>
              )}
              {result.pveVersion && (
                <div className="flex justify-between gap-2">
                  <dt className="text-slate-500">PVE</dt>
                  <dd className="truncate">{result.pveVersion}</dd>
                </div>
              )}
            </dl>
          )}
          <p className="mt-2 text-[11px] text-slate-500">Checked {new Date(result.checkedAt).toLocaleTimeString()}</p>
        </div>
      )}
    </div>
  );
}

