      ) : (
        <div className="card p-0">
          <div className="overflow-x-auto">
            <table className="table-shell">
              <thead>
                <tr>
                  <th>Node</th>
                  <th>Status</th>
                  <th>Servers</th>
                  <th className="min-w-52">Committed RAM</th>
                  <th>Subnet</th>
                  <th>Last seen</th>
                  <th className="text-right">Actions</th>
                </tr>
              </thead>
              <tbody>
                {nodes.map((n) => {
                  const committed = n.servers.reduce((sum, s) => sum + s.plan.ramMB, 0);
                  const ratio = n.capacityRamMB > 0 ? committed / n.capacityRamMB : 1;
                  return (
                    <tr key={n.id}>
                      <td>
                        <div className="flex items-center gap-2">
                          <Link href={`/admin/nodes/${n.id}`} className="font-medium hover:text-brand-300">
                            {n.name}
                          </Link>
                          {n.isPrimary && <Badge tone="brand">primary</Badge>}
                          {!n.enabled && <Badge tone="slate">disabled</Badge>}
                        </div>
                        <div className="mt-0.5 font-mono text-xs text-slate-500">{n.pveNode} · {n.publicIp}</div>
                      </td>
                      <td>
                        <StatusDot status={statusMap[n.status] ?? "STOPPED"} label={n.status} />
                      </td>
                      <td>{n.servers.length}</td>
                      <td>
                        <div className="mb-1 flex justify-between text-xs text-slate-400">
                          <span>{(committed / 1024).toFixed(1)} GB</span>
                          <span>{(ratio * 100).toFixed(0)}% of {(n.capacityRamMB / 1024).toFixed(0)} GB</span>
                        </div>
                        <MeterBar value={committed} max={n.capacityRamMB} color={capColor(ratio)} />
                      </td>
                      <td className="font-mono text-xs">{n.subnetPrefix}0/24</td>
                      <td className="text-xs text-slate-400">{n.lastSeenAt ? timeAgo(n.lastSeenAt) : "never"}</td>
                      <td>
                        <div className="flex items-center justify-end gap-2">
                          <TestNodeButton id={n.id} compact />
                          <EnableToggle id={n.id} enabled={n.enabled} />
                          <Link href={`/admin/nodes/${n.id}`} className="btn-secondary py-1.5">
                            Manage
                          </Link>
                        </div>
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        </div>
      )}

      <p className="text-xs text-slate-500">
        Note: cross-host private networking between nodes is not automatic. Each node NATs its own /24 behind its own
        public IP; VMs on different physical hosts cannot reach each other over the 10.20.x.x LAN without a VPN/overlay
        (WireGuard/VXLAN). See the header of <span className="font-mono">scripts/onboard-node.sh</span> for details.
      </p>
    </div>
  );
}

import Link from "next/link";
import { requireAdmin } from "@/lib/auth";
import { PageHeader } from "@/components/ui/primitives";
import { NodeForm } from "@/components/admin/NodeForms";
import { suggestNodeDefaults } from "@/lib/actions-nodes";

export const dynamic = "force-dynamic";

export default async function AdminNodeNew() {
  await requireAdmin();
  const defaults = await suggestNodeDefaults();

  return (
    <div className="space-y-6">
      <PageHeader title="Add compute node" sub="Register an onboarded Proxmox host so the scheduler can provision onto it.">
        <Link href="/admin/nodes" className="btn-secondary">
          Back to nodes
        </Link>
      </PageHeader>

      <div className="rounded-xl border border-brand-500/30 bg-brand-500/10 px-4 py-3 text-sm text-brand-200">
        <p className="font-medium">Suggested values for node #{defaults.ordinal}</p>
        <p className="mt-1 text-brand-200/80">
          Subnet <span className="font-mono">{defaults.subnetPrefix}0/24</span>, NAT chain{" "}
          <span className="font-mono">{defaults.natChain}</span>. These are pre-filled below and are non-colliding with
          existing nodes. Run <span className="font-mono">scripts/onboard-node.sh</span> on the target host first — it
          prints the exact API URL, token ID and secret to paste here.
        </p>
      </div>

      <div className="card">
        <NodeForm defaults={defaults} />
      </div>
    </div>
  );
}

